(function() {
  const scopeId = 'main_productivity_result';

  // 教学假设与局限说明
  const teachingAssumptions = [
    "平行趋势假设：在没有 AI 干预的情况下，处理组和对照组的生产力变化趋势应保持一致。",
    "无预期行为：代理在正式获得 AI 访问权之前不会提前改变工作行为。",
    "回归模型控制了时间不变的个人特征和时间变化的任期因素，以隔离 AI 的因果效应。"
  ];

  const limitations = [
    "数据来源于单一 Fortune 500 软件公司的客服中心，可能不完全适用于其他行业。",
    "主要报告意向治疗效应 (ITT)，实际依从性（Adherence）平均为 38%，存在异质性。",
    "长期影响（如技能退化或组织依赖）尚未在样本期内完全显现。"
  ];

  // 从 runtime_data 获取真实表格数据
  const tables = window.paperMindData?.tables || [];
  const table3 = tables.find(t => t.id === 'p45-Table_3');

  if (!table3) {
    console.error('Table 3 not found in runtime data');
    return;
  }

  // 解析表 3 关键行数据 (Post AI X Ever Treated)
  const mainRow = table3.rows.find(r => r.id === 'row_post_ai_x_evertreated');
  const dvMeanRow = table3.rows.find(r => r.id === 'row_dv_mean');

  if (!mainRow || !dvMeanRow) {
    console.error('Required rows not found in Table 3');
    return;
  }

  // 提取数值并处理字符串格式 (如 "-3.750*** (0.476)")
  function parseValue(str) {
    if (!str) return null;
    // 移除显著性标记 *** 和括号内的标准误
    const clean = str.replace(/\*+/g, '').split('(')[0].trim();
    return clean ? parseFloat(clean) : null;
  }

  function parseMean(str) {
    if (!str) return null;
    return parseFloat(str);
  }

  const metrics = [
    {
      id: 'aht',
      label: '平均处理时长 (AHT)',
      unit: '分钟',
      coef: parseValue(mainRow.values['(1) AHT']),
      mean: parseMean(dvMeanRow.values['(1) AHT']),
      highlight: false
    },
    {
      id: 'cph',
      label: '每小时对话数 (CPH)',
      unit: '次',
      coef: parseValue(mainRow.values['(2) Calls/Hr']),
      mean: parseMean(dvMeanRow.values['(2) Calls/Hr']),
      highlight: true
    },
    {
      id: 'rr',
      label: '解决率 (Res. Rate)',
      unit: '比例',
      coef: parseValue(mainRow.values['(3) Res. Rate']),
      mean: parseMean(dvMeanRow.values['(3) Res. Rate']),
      highlight: false
    },
    {
      id: 'nps',
      label: '客户满意度 (NPS)',
      unit: '分',
      coef: parseValue(mainRow.values['(4) NPS']),
      mean: parseMean(dvMeanRow.values['(4) NPS']),
      highlight: false
    }
  ];

  // 计算百分比变化
  metrics.forEach(m => {
    if (m.mean && m.mean !== 0) {
      m.pctChange = ((m.coef / m.mean) * 100).toFixed(1);
    } else {
      m.pctChange = null;
    }
  });

  // 渲染表格
  const tbody = document.querySelector(`#${scopeId} #table-body`);
  if (tbody) {
    tbody.innerHTML = metrics.map(m => {
      const sig = m.coef < 0 ? 'negative' : (m.coef > 0 ? 'positive' : '');
      const pctDisplay = m.pctChange ? `${m.pctChange}%` : '-';
      const sigStars = mainRow.values['(1) AHT'].includes('***') || mainRow.values['(2) Calls/Hr'].includes('***') ? '***' : (mainRow.values['(3) Res. Rate'].includes('*') ? '*' : '');

      // 动态获取显著性标记 (简化处理，实际应根据每列判断)
      let stars = '';
      if(m.id === 'aht' && mainRow.values['(1) AHT'].includes('***')) stars = '***';
      else if(m.id === 'cph' && mainRow.values['(2) Calls/Hr'].includes('***')) stars = '***';
      else if(m.id === 'rr' && mainRow.values['(3) Res. Rate'].includes('*')) stars = '*';

      return `
        <tr data-metric="${m.id}">
          <td>${m.label}</td>
          <td class="${sig}">${m.coef.toFixed(3)} ${stars}</td>
          <td>${m.unit}</td>
          <td>${stars}</td>
          <td>${m.mean}</td>
          <td class="${sig}">${pctDisplay}</td>
        </tr>
      `;
    }).join('');
  }

  // 绘制 Canvas 图表
  const canvas = document.querySelector(`#${scopeId} #productivityChart`);
  const tooltip = document.querySelector(`#${scopeId} #chart-tooltip`);

  if (canvas && canvas.getContext) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const padding = 60;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // 清空画布
    ctx.clearRect(0, 0, width, height);

    // 绘制坐标轴
    ctx.beginPath();
    ctx.strokeStyle = '#718096';
    ctx.lineWidth = 1;
    // Y 轴 (0 线)
    const zeroY = padding + chartHeight / 2;
    ctx.moveTo(padding, zeroY);
    ctx.lineTo(width - padding, zeroY);
    // X 轴
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.stroke();

    // 标签
    ctx.fillStyle = '#718096';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('0%', padding, zeroY + 15);
    ctx.fillText('指标', width / 2, height - 20);
    ctx.save();
    ctx.translate(20, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('变化幅度 (%)', 0, 0);
    ctx.restore();

    // 绘制条形
    const barWidth = 60;
    const gap = 40;
    const startX = padding + 40;

    metrics.forEach((m, index) => {
      if (m.pctChange === null) return;

      const val = parseFloat(m.pctChange);
      const maxVal = 15; // 最大刻度
      const scale = chartHeight / 2 / maxVal;

      const x = startX + index * (barWidth + gap);
      const barHeight = Math.abs(val) * scale;
      const y = val > 0 ? zeroY - barHeight : zeroY;

      // 颜色
      ctx.fillStyle = m.id === 'cph' ? '#2C5282' : (val > 0 ? '#276749' : '#C53030');
      if (m.highlight) ctx.fillStyle = '#2C5282';

      ctx.fillRect(x, y, barWidth, barHeight);

      // 数值标签
      ctx.fillStyle = '#1a202c';
      ctx.fillText(`${val > 0 ? '+' : ''}${val}%`, x + barWidth / 2, val > 0 ? y - 5 : y + barHeight + 15);

      // 存储点击区域
      m.hitArea = { x, y, w: barWidth, h: barHeight };
    });

    // 交互逻辑
    canvas.addEventListener('mousemove', (e) => {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      let hovered = null;
      metrics.forEach(m => {
        if (m.hitArea && 
            mouseX >= m.hitArea.x && mouseX <= m.hitArea.x + m.hitArea.w &&
            mouseY >= Math.min(m.hitArea.y, m.hitArea.y + m.hitArea.h) && 
            mouseY <= Math.max(m.hitArea.y, m.hitArea.y + m.hitArea.h)) {
          hovered = m;
        }
      });

      if (hovered) {
        canvas.style.cursor = 'pointer';
        tooltip.classList.add('visible');
        tooltip.style.left = (e.clientX - rect.left + 10) + 'px';
        tooltip.style.top = (e.clientY - rect.top - 10) + 'px';

        const explanation = hovered.id === 'cph' 
          ? 'CPH 增幅 (+14%) 大于 AHT 降幅 (-9%)，说明 AI 增强了多任务处理能力。'
          : (hovered.id === 'aht' ? '单次对话处理时间缩短，效率提升。' : '质量指标保持稳定或小幅提升。');

        tooltip.innerHTML = `<strong>${hovered.label}</strong><br>变化：${hovered.pctChange}%<br><small>${explanation}</small>`;

        // 高亮对应表格行
        document.querySelectorAll(`#${scopeId} .data-table tr`).forEach(tr => tr.style.background = '');
        const row = document.querySelector(`#${scopeId} tr[data-metric="${hovered.id}"]`);
        if(row) row.style.background = '#ebf8ff';

      } else {
        canvas.style.cursor = 'default';
        tooltip.classList.remove('visible');
        document.querySelectorAll(`#${scopeId} .data-table tr`).forEach(tr => tr.style.background = '');
      }
    });

    canvas.addEventListener('mouseleave', () => {
      tooltip.classList.remove('visible');
      document.querySelectorAll(`#${scopeId} .data-table tr`).forEach(tr => tr.style.background = '');
    });
  }

  // 重置按钮
  const resetBtn = document.querySelector(`#${scopeId} #reset-view`);
  if(resetBtn) {
    resetBtn.addEventListener('click', () => {
      tooltip.classList.remove('visible');
      document.querySelectorAll(`#${scopeId} .data-table tr`).forEach(tr => tr.style.background = '');
      document.querySelectorAll(`#${scopeId} .metric-card`).forEach(c => c.classList.remove('active'));
    });
  }

  // 来源按钮处理 (由内核接管)
  document.querySelectorAll(`#${scopeId} .source-btn`).forEach(btn => {
    btn.addEventListener('click', (e) => {
      // 不执行任何操作，内核通过 data-source 属性处理
      e.preventDefault();
    });
  });

  // 提问按钮处理
  document.querySelectorAll(`#${scopeId} .ask-btn`).forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      // 内核通过 data-ask 和 data-node 处理
    });
  });

})();
